import numpy as np

def select_next_node(cur_truck_pos, depot_pos, all_truck_pos, unvisited_customers):
    best_node = 0
    best_score = float('inf')
    beta = 0.5          # penalty weight
    epsilon = 1e-6      # avoid division by zero

    for i, customer in enumerate(unvisited_customers):
        dist_cur = np.linalg.norm(customer - cur_truck_pos)

        # Distance from this customer to the nearest other truck (excluding current)
        min_other_dist = float('inf')
        for other_pos in all_truck_pos:
            if not np.array_equal(other_pos, cur_truck_pos):
                d = np.linalg.norm(customer - other_pos)
                if d < min_other_dist:
                    min_other_dist = d

        # If no other trucks exist, min_other_dist remains inf -> penalty = 0
        if np.isinf(min_other_dist):
            penalty = 0.0
        else:
            penalty = beta / (min_other_dist + epsilon)

        score = dist_cur * (1 + penalty)

        if score < best_score:
            best_score = score
            best_node = i

    return best_node
